local Embroiderer = {}
local PRODUCTS = {
    embroidered_cloth = { name = "Vezano blago", threadCost = 3, clothCost = 1, time = 5, cost = 50, happiness = 2, prestige = 3, description = "Vezano blago za oblačila." },
    heraldic_banner = { name = "Heraldična zastava", threadCost = 5, clothCost = 2, goldThreadCost = 1, time = 14, cost = 300, prestige = 15, description = "Družinska zastava z grbom." },
    altar_cloth = { name = "Oltarno pregrinjalo", threadCost = 8, clothCost = 2, goldThreadCost = 2, time = 20, cost = 500, prestige = 10, faith = 15, description = "Bogato vezano za cerkev." },
    vestment = { name = "Mašna oblačila", threadCost = 10, clothCost = 3, goldThreadCost = 3, time = 30, cost = 800, prestige = 15, faith = 20, description = "Vezana mašna oblačila." },
    tapestry_panel = { name = "Vezana tapiserija", threadCost = 15, clothCost = 5, time = 45, cost = 1000, prestige = 25, happiness = 8, description = "Vezana tapiserija za stene." },
    royal_robe = { name = "Kraljevski plašč", threadCost = 20, clothCost = 5, goldThreadCost = 5, ermineCost = 3, time = 60, cost = 2000, prestige = 40, happiness = 15, description = "Kraljevski plašč z hermelinom." },
}
local BUILDINGS = {
    workshop = { name = "Veziljska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    embroidery_studio = { name = "Veziljski atelje", cost = { gold = 1000, wood = 200, stone = 200 }, upkeep = 25, qualityBonus = 20 },
    gold_thread_shop = { name = "Zlatonitna delavnica", cost = { gold = 1500, wood = 200, stone = 300, gold = 50 }, upkeep = 30, qualityBonus = 15 },
    royal_embroidery = { name = "Kraljevska vezilja", cost = { gold = 4000, wood = 400, stone = 600, gold = 100 }, upkeep = 80, qualityBonus = 35, prestigeBonus = 20 },
}
Embroiderer.threadStock = 20; Embroiderer.clothStock = 10; Embroiderer.goldThreadStock = 5; Embroiderer.ermineStock = 3
Embroiderer.productStock = {}; Embroiderer.buildings = {}; Embroiderer.embroiderer = nil; Embroiderer.activeMaking = {}; Embroiderer.totalProducts = 0; Embroiderer.dayTimer = 0
function Embroiderer.init() Embroiderer.threadStock=20; Embroiderer.clothStock=10; Embroiderer.goldThreadStock=5; Embroiderer.ermineStock=3; Embroiderer.productStock={}; Embroiderer.buildings={}; Embroiderer.embroiderer=nil; Embroiderer.activeMaking={}; Embroiderer.totalProducts=0; Embroiderer.dayTimer=0; print("[Embroiderer] Royal Embroiderer & Needlework System initialized (6 products, 4 buildings)") end
function Embroiderer.hireEmbroiderer(n,s) s=s or math.random(40,85); local c=300+s*6; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Embroiderer.embroiderer={name=n or ("Vezilja "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezilja najeta: %s (spretnost: %d)",Embroiderer.embroiderer.name,s),"success") end; return true end
function Embroiderer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Embroiderer.build(id) local ok,e=Embroiderer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Embroiderer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Embroiderer.getQualityBonus() local b=0; for _,bd in ipairs(Embroiderer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Embroiderer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.threadCost and Embroiderer.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.clothCost and Embroiderer.clothStock<(d.clothCost or 0) then return false,"Premalo blaga" end; if d.goldThreadCost and Embroiderer.goldThreadStock<(d.goldThreadCost or 0) then return false,"Premalo zlatih niti" end; if d.ermineCost and Embroiderer.ermineStock<(d.ermineCost or 0) then return false,"Premalo hermelina" end; if #Embroiderer.buildings==0 then return false,"Potrebna delavnica" end; if not Embroiderer.embroiderer then return false,"Potrebna vezilja" end; return true end
function Embroiderer.make(pt) local ok,e=Embroiderer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.threadCost then Embroiderer.threadStock=Embroiderer.threadStock-d.threadCost end; if d.clothCost then Embroiderer.clothStock=Embroiderer.clothStock-d.clothCost end; if d.goldThreadCost then Embroiderer.goldThreadStock=Embroiderer.goldThreadStock-d.goldThreadCost end; if d.ermineCost then Embroiderer.ermineStock=Embroiderer.ermineStock-d.ermineCost end; local t=d.time; if Embroiderer.embroiderer then t=math.max(1,t-math.floor(Embroiderer.embroiderer.skill/10)) end; table.insert(Embroiderer.activeMaking,{id="emb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,faith=d.faith or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezenje: %s (%d dni)",d.name,t),"info") end; return true end
function Embroiderer.completeMaking(m) local q=1.0+(Embroiderer.getQualityBonus()/100); if Embroiderer.embroiderer then q=q+(Embroiderer.embroiderer.skill/200) end; q=math.min(2.5,q); Embroiderer.productStock[m.productType]=(Embroiderer.productStock[m.productType] or 0)+1; Embroiderer.totalProducts=Embroiderer.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,m.faith) end; if Embroiderer.embroiderer then Embroiderer.embroiderer.itemsMade=Embroiderer.embroiderer.itemsMade+1; if math.random()<0.15 then Embroiderer.embroiderer.skill=math.min(100,Embroiderer.embroiderer.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezava dokončana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Embroiderer.update(dt) if not _G.state then return end; Embroiderer.dayTimer=Embroiderer.dayTimer+dt; if Embroiderer.dayTimer>=30 then Embroiderer.dayTimer=0; for i=#Embroiderer.activeMaking,1,-1 do local m=Embroiderer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Embroiderer.completeMaking(m); table.remove(Embroiderer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Embroiderer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Embroiderer.embroiderer then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Embroiderer.getStats() return {threadStock=Embroiderer.threadStock,clothStock=Embroiderer.clothStock,goldThreadStock=Embroiderer.goldThreadStock,ermineStock=Embroiderer.ermineStock,productStock=Embroiderer.productStock,numBuildings=#Embroiderer.buildings,hasEmbroiderer=Embroiderer.embroiderer~=nil,embroidererName=Embroiderer.embroiderer and Embroiderer.embroiderer.name or "—",embroidererSkill=Embroiderer.embroiderer and Embroiderer.embroiderer.skill or 0,activeMaking=#Embroiderer.activeMaking,totalProducts=Embroiderer.totalProducts} end
return Embroiderer
